function timeToSeconds($time) {
    list($m, $s) = explode(':', $time);
    return ($m * 60) + $s;
}

foreach ($data as $chapter => $questions) {
    $lesson_id = $chapter_map[$chapter];
    if (!$lesson_id) {
        echo "Error: No lesson ID map for Chapter $chapter\n";
        continue;
    }

    echo "Processing Chapter $chapter (Lesson ID: $lesson_id)...\n";

    // Delete existing QUIZ questions for this lesson
    $stmt = $mysqli->prepare("DELETE FROM tb_test WHERE lesson_id = ? AND test_type = 'QUIZ'");
    $stmt->bind_param("i", $lesson_id);
    $stmt->execute();
    echo "  Deleted " . $stmt->affected_rows . " existing questions.\n";
    $stmt->close();

    // Insert new questions
    $stmt = $mysqli->prepare("INSERT INTO tb_test (lesson_id, question, choice_a, choice_b, choice_c, choice_d, correct, timeshow, test_type, test_order) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'QUIZ', ?)");
    
    $order = 1;
    foreach ($questions as $q) {
        $seconds = timeToSeconds($q['time']);
        $choice_a = $q['c'][0];
        $choice_b = $q['c'][1];
        $choice_c = $q['c'][2];
        $choice_d = $q['c'][3];
        $correct = $q['ans'];
        
        // Remove prefixes from choices (e.g., "1. " -> "") if desired? 
        // User prompt has "1. ...", "2. ...". I will keep them as is for now as database usually stores full string, 
        // OR I can clean them. User didn't explicitly ask to clean them in DB, only in display (previous task).
        // But for consistency let's store them as provided.
        // Actually, the previous task REMOVED prefixes in JS.
        // Let's stripping the "1. ", "2. " prefix to be clean if possible? 
        // No, let's stick to EXACTLY what was provided to be safe usually. But user's text has "1.", "2." etc.
        // I will keep them to match user input specifically.
        
        $stmt->bind_param("issssssii", $lesson_id, $q['q'], $choice_a, $choice_b, $choice_c, $choice_d, $correct, $seconds, $order);
        
        if ($stmt->execute()) {
            echo "  Inserted Q$order at " . $q['time'] . " ($seconds s)\n";
        } else {
            echo "  Error Inserting Q$order: " . $stmt->error . "\n";
        }
        $order++;
    }
    $stmt->close();
}

echo "Update Complete!\n";
